import * as T from '/vendor/three.module.js';
import {GLTFLoader} from '/vendor/loaders/GLTFLoader.js';
import {OrbitControls} from '/vendor/OrbitControls.js';
import {three,buildBackpack,DEFAULT_LOOK,charmModel} from '/simulations/backpack.mjs';
import {buildCar,CARS} from '/simulations/coaster-cars.mjs';

// Review-only compositions. The bag, cars, charms and hero reuse the game assets.
// Room furniture and terrain are explicit study geometry, never registered as production assets.
export async function makeScene(host,{kind='room',onPick=()=>{}}={}){
 await three();
 const renderer=new T.WebGLRenderer({antialias:true,alpha:false,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;host.prepend(renderer.domElement);renderer.domElement.style.cssText='position:absolute;inset:0;width:100%;height:100%;touch-action:none';
 const scene=new T.Scene();scene.background=new T.Color(kind==='intro'?'#14222d':'#dfe5d4');const camera=new T.PerspectiveCamera(35,1,.1,150);camera.position.set(9,9,13);
 const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,1,0);controls.enableDamping=true;controls.maxPolarAngle=1.45;controls.minDistance=4;controls.maxDistance=24;controls.enablePan=false;
 scene.add(new T.HemisphereLight('#fff2da','#9daaa3',2.1));const sun=new T.DirectionalLight('#fff0d1',3.2);sun.position.set(-6,12,8);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-12,right:12,top:12,bottom:-12});sun.shadow.bias=-.001;scene.add(sun);const fill=new T.DirectionalLight('#d1dfff',1);fill.position.set(8,4,-4);scene.add(fill);
 const root=new T.Group();scene.add(root);const picks=[];const anim=[];let dead=false,frame=0;
 const mat=(c,metal=0)=>new T.MeshStandardMaterial({color:c,roughness:metal?.3:.72,metalness:metal});
 function box(x,y,z,w,h,d,c,parent=root){const m=new T.Mesh(new T.BoxGeometry(w,h,d),mat(c));m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;parent.add(m);return m}
 function ball(x,y,z,r,c,parent=root){const m=new T.Mesh(new T.SphereGeometry(r,24,16),mat(c));m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
 function cyl(x,y,z,r,h,c,parent=root,n=48){const m=new T.Mesh(new T.CylinderGeometry(r,r,h,n),mat(c));m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;parent.add(m);return m}
 function tag(obj,id){obj.userData.pick=id;picks.push(obj);return obj}
 function normalize(obj,height){const bounds=new T.Box3().setFromObject(obj),size=bounds.getSize(new T.Vector3()),c=bounds.getCenter(new T.Vector3());const g=new T.Group();g.add(obj);obj.position.sub(new T.Vector3(c.x,bounds.min.y,c.z));g.scale.setScalar(height/Math.max(size.y,.01));return g}
 async function asset(url,h,x,y,z,id){try{const gltf=await new GLTFLoader().loadAsync(url);if(dead)return null;const g=normalize(gltf.scene,h);g.position.set(x,y,z);g.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});root.add(g);if(id)tag(g,id);return g}catch(e){host.dispatchEvent(new CustomEvent('asset-warning',{detail:url}));return null}}
 function plant(x,z,s=1,parent=root){const p=new T.Group();parent.add(p);p.position.set(x,0,z);p.scale.setScalar(s);cyl(0,.2,0,.25,.4,'#bd7b64',p);for(let i=0;i<5;i++){const a=i*1.256;const leaf=ball(Math.cos(a)*.22,.55+i*.06,Math.sin(a)*.22,.22,i%2?'#729e70':'#4c8066',p);leaf.scale.set(.65,1.5,.8);leaf.rotation.z=Math.sin(a)*.5}return p}
 function house(x,z,color='#f6d1aa',s=1,parent=root){const g=new T.Group();g.position.set(x,0,z);g.scale.setScalar(s);parent.add(g);box(0,.55,0,1.3,1.1,1.15,color,g);const roof=new T.Mesh(new T.CylinderGeometry(0,1.02,.75,4),mat('#bd7382'));roof.rotation.y=Math.PI/4;roof.position.y=1.45;roof.castShadow=true;g.add(roof);box(0,.35,.585,.26,.7,.05,'#578c81',g);for(const xx of [-.4,.4]){box(xx,.7,.6,.25,.32,.04,'#fff1b7',g);box(xx,.7,.63,.025,.32,.015,'#faf2dc',g)}return g}
 function tree(x,z,s=1,parent=root){const g=new T.Group();g.position.set(x,0,z);g.scale.setScalar(s);parent.add(g);cyl(0,.5,0,.09,1,'#a87d60',g,10);ball(0,1.2,0,.52,'#8da87a',g);ball(-.3,1,.1,.35,'#a8bd81',g);ball(.24,1.35,-.03,.37,'#749574',g);return g}
 function car(x,y,z,id='buggy',scale=.7){const c=buildCar(T,CARS.find(c=>c.id===id)||CARS[0]);c.scale.setScalar(scale);c.position.set(x,y,z);root.add(c);return c}
 let bag,wall,rug,trophy,hero,boardGroup;
 async function room(){controls.target.set(0,1.5,0);camera.position.set(8,7.8,12);box(0,-.25,0,8,.5,5.8,'#e5cfad');box(0,.02,0,7.8,.05,5.6,'#f5e6ce');wall=box(0,2.1,-2.8,8,4.2,.22,'#bccebb');box(-4,2,-.1,.2,4,5.6,'#d9bdcc');for(let x=-3.8;x<4;x+=.28)box(x,2.15,-2.66,.025,3.9,.025,'#d7e2cf');box(0,.3,-2.6,7.8,.55,.12,'#eff0dc');
 // Arched mirror, display shelves, sofa, rug and little toy table.
 const mirror=new T.Mesh(new T.CircleGeometry(.8,48),mat('#b3cbd0',.5));mirror.position.set(-2.65,2.35,-2.64);root.add(mirror);const rim=new T.Mesh(new T.TorusGeometry(.84,.055,12,64),mat('#d8ae65',.7));rim.position.copy(mirror.position);root.add(rim);tag(mirror,'wardrobe');
 box(-2.5,.65,-1.4,1.7,.55,.8,'#c994ae');box(-2.5,1.05,-1.75,1.7,.65,.22,'#dba9bd');for(const x of [-3.36,-1.64])box(x,.85,-1.4,.2,.7,.9,'#dfb2c6');for(const x of [-3,-2])box(x,.92,-1.36,.63,.13,.61,'#f5d5d8');
 for(const y of [1.5,2.65]){box(1.5,y,-2.27,3.4,.12,.85,'#e0bd8b');for(const x of [.2,2.8])box(x,y-.15,-2.47,.08,.3,.25,'#b7936c')}
 rug=cyl(0,.065,.7,2.05,.035,'#d8a0ad');rug.scale.z=.62;const ring=new T.Mesh(new T.TorusGeometry(1.87,.025,8,64),mat('#f9e4cd'));ring.rotation.x=Math.PI/2;ring.scale.y=.62;ring.position.set(0,.09,.7);root.add(ring);
 cyl(1.8,.48,.6,.65,.12,'#eed9b6');for(const x of [1.45,2.15])box(x,.24,.6,.09,.48,.09,'#b48e72');plant(3.1,1.8,1.4);plant(-3.3,1.65,.8);
 bag=buildBackpack(DEFAULT_LOOK,{charms:[]});bag.group.position.set(-.7,1.58,-2.25);bag.group.scale.setScalar(.65);root.add(tag(bag.group,'backpack'));
 trophy=new T.Group();root.add(tag(trophy,'trophies'));trophy.position.set(1.1,2.72,-2.2);cyl(0,.05,0,.23,.1,'#6d8371',trophy);cyl(0,.22,0,.055,.3,'#ddad57',trophy);const cup=new T.Mesh(new T.CylinderGeometry(.3,.13,.35,32),mat('#dca744',.65));cup.position.y=.52;trophy.add(cup);for(const x of [-.3,.3]){const h=new T.Mesh(new T.TorusGeometry(.15,.035,8,24),mat('#dca744',.65));h.position.set(x,.5,0);trophy.add(h)}
 const toy=car(2.3,1.58,-2.2,'comet',.32);tag(toy,'toys');
 hero=await asset('/studies/moon-mission/heroes/A1-clay-tee.glb',1.65,-.85,.1,.6,'wardrobe');
 const charm=await charmModel('school-roof').catch(()=>null);if(charm&&!dead){const c=normalize(charm,.43);c.position.set(2.2,2.72,-2.2);root.add(tag(c,'charms'))} }
 function island(theme='Winchester'){root.clear();const moon=theme==='Moon Garden';scene.background.set(moon?'#adb9d0':'#dfe5d4');cyl(0,-.45,0,4.3,.7,moon?'#8e9eb0':'#ad9877',root,6);cyl(0,-.075,0,4.3,.1,moon?'#c8cbd2':'#aac68a',root,6);box(0,.003,0,6.7,.025,.6,moon?'#dcd7d1':'#e9d5b8');box(-.3,.006,0,.55,.03,6.3,'#e9d5b8');house(-1.9,-1.4,moon?'#d4e1e9':'#f3d4ae',1.2);house(1.8,-1.6,'#d4bad7',.9);house(1.7,1.6,'#e6b8b1',.72);tree(-2,1.7,1.1);tree(3,.2,.8);tree(-.6,-2.8,.8);plant(.9,.8);car(-.8,.12,0,'buggy',.35);controls.target.set(0,.8,0);camera.position.set(9,9,12)}
 async function intro(){root.clear();controls.enabled=false;camera.position.set(0,1.7,5.3);controls.target.set(0,.9,0);bag=buildBackpack(DEFAULT_LOOK,{charms:[]});root.add(bag.group);bag.group.position.y=.2;bag.group.rotation.y=-.25;const floor=cyl(0,-.5,0,2.8,.08,'#213541');const spot=new T.SpotLight('#ffe4ae',35,20,.5,.7,1.4);spot.position.set(0,6,1.5);spot.target=bag.group;scene.add(spot);anim.push(t=>{bag.group.position.y=.2+Math.sin(t*1.6)*.06;bag.group.rotation.y=-.25+Math.sin(t*.4)*.2;bag.update?.(.016);spot.intensity=34+Math.sin(t*7)*Math.sin(t*13)*2});}
 function design(tiles){root.clear();boardGroup=new T.Group();root.add(boardGroup);controls.target.set(0,0,0);camera.position.set(9,10,12);tiles.forEach((tile,i)=>{const q=tile.q,r=tile.r,x=1.67*(q+r*.5),z=1.45*r;const g=new T.Group();g.position.set(x,0,z);boardGroup.add(g);const base=cyl(0,-.23,0,.94,.4,tile.terrain==='water'?'#a3c9cb':tile.terrain==='hill'?'#91a783':'#b7ce98',g,6);tag(base,'tile:'+i);const h=tile.terrain==='hill'?.25:0;if(h)cyl(0,.05,0,.8,.35,'#a5b78d',g,6);switch(tile.item){case 'home':house(0,0,'#f2cfba',.68,g);break;case 'forest':tree(-.2,-.1,.75,g);tree(.3,.25,.5,g);break;case 'garden':for(let k=0;k<3;k++)plant((k-1)*.35,.1,.65,g);break;case 'cafe':house(0,0,'#edc68b',.7,g);cyl(.4,.15,.55,.22,.3,'#d0a0ab',g);break;case 'play':for(const xx of [-.4,.4])box(xx,.6,0,.08,1.2,.08,'#b38367',g);box(0,1.2,0,1,.08,.08,'#ba8d69',g);box(0,.35,0,.45,.08,.25,'#d78f9f',g);for(const xx of [-.2,.2])box(xx,.78,0,.02,.85,.02,'#efe6d5',g);break;case 'track':const track=new T.Mesh(new T.TorusGeometry(.6,.1,8,40),mat('#db915a'));track.rotation.x=Math.PI/2;track.position.y=.1;g.add(track);break;case 'pond':cyl(0,.015,0,.7,.045,'#81bbca',g);plant(.5,.5,.5,g);break;case 'award':cyl(0,.13,0,.35,.26,'#dbcba6',g);ball(0,.5,0,.22,'#dfb458',g);break;case 'pet':ball(0,.25,0,.22,'#ddc2a3',g);ball(.16,.4,0,.16,'#ddc2a3',g);break;}g.position.y+=h;});}
 const ready=kind==='intro'?intro():kind==='room'?room():kind==='island'?Promise.resolve(island()):Promise.resolve();await ready;
 const ray=new T.Raycaster(),mouse=new T.Vector2();let down=null;const pd=e=>{down=[e.clientX,e.clientY]};const pu=e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>7)return;const r=renderer.domElement.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(mouse,camera);const hit=ray.intersectObjects(root.children,true).find(h=>{let o=h.object;while(o){if(o.userData.pick)return true;o=o.parent}return false});if(hit){let o=hit.object;while(o&&!o.userData.pick)o=o.parent;onPick(o.userData.pick)}else if(kind==='intro')onPick('intro')};renderer.domElement.addEventListener('pointerdown',pd);renderer.domElement.addEventListener('pointerup',pu);
 const resize=()=>{const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.fov=Math.min(78,35/Math.min(1,w/h));camera.updateProjectionMatrix()};const obs=new ResizeObserver(resize);obs.observe(host);resize();
 const tick=ms=>{if(dead)return;controls.update();for(const f of anim)f(ms/1000);renderer.render(scene,camera);frame=requestAnimationFrame(tick)};frame=requestAnimationFrame(tick);
 return {scene,root,renderer,camera,design,island,async reveal(n){if(n===1){const c=await charmModel('school-roof');if(dead)return;const g=normalize(c,.7);g.position.set(0,1.25,1.3);root.add(g);anim.push(t=>g.rotation.y=t*.6)}else{for(let i=0;i<5;i++){const c=car(Math.cos(i*1.256)*1.25,.65+Math.sin(i*1.256)*.5,0,['buggy','comet','rocket','shark','monster'][i],.22);anim.push(t=>c.rotation.y=t*.3)}}},theme(c){wall?.material.color.set(c);rug?.material.color.set(c)},moveTrophy(){if(trophy)trophy.position.x=trophy.position.x===1.1?2.7:1.1},dress(c){hero?.traverse(o=>{if(o.isMesh&&o.material){o.material=o.material.clone();o.material.color?.lerp(new T.Color(c),.25)}})},openBag(){bag?.setOpen(bag.open?0:1)},capture(example){island(example==='moon'?'Moon Garden':'Winchester');if(example==='garden'){root.children.slice(4).forEach(o=>root.remove(o));for(let i=0;i<7;i++)plant(Math.cos(i)*2,Math.sin(i)*2,1.2)}},dispose(){dead=true;cancelAnimationFrame(frame);obs.disconnect();controls.dispose();root.traverse(o=>{o.geometry?.dispose();if(o.material){for(const m of Array.isArray(o.material)?o.material:[o.material]){m.map?.dispose();m.dispose()}}});renderer.dispose();renderer.domElement.remove()}};
}
